1	//! `Vec<Item>` → Bedrock Converse `Message` / `SystemContentBlock` translation.
2	//!
3	//! Rules per SMA-329 spec §6 "Wire translation":
4	//! - `Item::System` → `SystemContentBlock::Text`; system blocks are never mixed
5	//!   into the `messages` slice.
6	//! - Strictly alternating user / assistant turns required by Converse.
7	//! - First message must be `user` (a synthetic empty user turn is prepended when
8	//!   the first real item is assistant-role).
9	//! - `Item::ToolCall` / `ContentPart::ToolUse` → `ContentBlock::ToolUse` on
10	//!   the assistant turn.
11	//! - `Item::ToolResult` queued pending → flushed as `ContentBlock::ToolResult`
12	//!   blocks prepended to the next user turn.
13	//! - Empty conversation (no messages after system extraction) → error.
14	
15	use aws_sdk_bedrockruntime::types::{
16	    ContentBlock, ConversationRole, Message, SystemContentBlock, ToolResultBlock,
17	    ToolResultContentBlock, ToolUseBlock,
18	};
19	use paigasus_helikon_core::{ContentPart, Item, ModelError};
20	#[cfg(test)]
21	use serde_json::{json, Value};
22	
23	use crate::document::value_to_document;
24	
25	/// Output of [`items_to_messages`].
26	#[derive(Debug)]
27	pub(crate) struct TranslatedMessages {
28	    /// System prompt blocks (`SystemContentBlock::Text`) extracted from
29	    /// `Item::System` entries.
30	    pub(crate) system: Vec<SystemContentBlock>,
31	    /// Strictly alternating conversation turns.
32	    pub(crate) messages: Vec<Message>,
33	}
34	
35	/// Translate the conversation into Bedrock Converse `Message`s.
36	///
37	/// Returns an error when the conversation is empty (has no non-system items
38	/// after stripping `Item::System` entries).
39	pub(crate) fn items_to_messages(items: &[Item]) -> Result<TranslatedMessages, ModelError> {
40	    let mut system: Vec<SystemContentBlock> = Vec::new();
41	    let mut messages: Vec<Message> = Vec::new();
42	
43	    // Pending assistant-side content blocks (ToolUse / Text for an assistant turn
44	    // that hasn't been flushed yet).
45	    let mut pending_assistant: Vec<ContentBlock> = Vec::new();
46	    // Pending ToolResult blocks to prepend to the next user turn.
47	    let mut pending_tool_results: Vec<ContentBlock> = Vec::new();
48	
49	    /// Flush `pending_assistant` into an assistant Message on `messages`.
50	    ///
51	    /// If the last message is already an assistant turn, the pending content
52	    /// blocks are appended to it (coalescing) rather than creating a new turn.
53	    fn flush_assistant(messages: &mut Vec<Message>, pending: &mut Vec<ContentBlock>) {
54	        if !pending.is_empty() {
55	            let content = std::mem::take(pending);
56	            if messages
57	                .last()
58	                .map(|m| m.role == ConversationRole::Assistant)
59	                .unwrap_or(false)
60	            {
61	                // Coalesce: append to the existing assistant turn.
62	                let last = messages.last_mut().unwrap();
63	                last.content.extend(content);
64	            } else {
65	                let msg = Message::builder()
66	                    .role(ConversationRole::Assistant)
67	                    .set_content(Some(content))
68	                    .build()
69	                    .expect("role + non-empty content always valid");
70	                messages.push(msg);
71	            }
72	        }
73	    }
74	
75	    /// Flush `pending_tool_results` into a new user Message on `messages`.
76	    fn flush_user_results(messages: &mut Vec<Message>, pending: &mut Vec<ContentBlock>) {
77	        if !pending.is_empty() {
78	            let content = std::mem::take(pending);
79	            let msg = Message::builder()
80	                .role(ConversationRole::User)
81	                .set_content(Some(content))
82	                .build()
83	                .expect("role + non-empty content always valid");
84	            messages.push(msg);
85	        }
86	    }
87	
88	    for item in items {
89	        match item {
90	            Item::System { content } => {
91	                // System items are pulled out to the `system` slot; flush any
92	                // in-progress turns first so ordering is preserved.
93	                flush_assistant(&mut messages, &mut pending_assistant);
94	                flush_user_results(&mut messages, &mut pending_tool_results);
95	                let text = text_of(content);
96	                system.push(SystemContentBlock::Text(text));
97	            }
98	
99	            Item::UserMessage { content } => {
100	                flush_assistant(&mut messages, &mut pending_assistant);
101	                // Pending tool results precede any user text in this turn.
102	                let mut blocks: Vec<ContentBlock> = std::mem::take(&mut pending_tool_results);
103	                for part in content {
104	                    match part {
105	                        ContentPart::Text { text } => {
106	                            blocks.push(ContentBlock::Text(text.clone()));
107	                        }
108	                        ContentPart::ToolResult { call_id, content } => {
109	                            // Native Anthropic-shaped ToolResult inside a UserMessage.
110	                            let result_block = build_tool_result_block(call_id, content);
111	                            blocks.push(ContentBlock::ToolResult(result_block));
112	                        }
113	                        _ => {
114	                            tracing::warn!(
115	                                target: "paigasus::bedrock::translate",
116	                                "unsupported ContentPart variant in UserMessage; skipping",
117	                            );
118	                        }
119	                    }
120	                }
121	                if !blocks.is_empty() {
122	                    if messages
123	                        .last()
124	                        .map(|m| m.role == ConversationRole::User)
125	                        .unwrap_or(false)
126	                    {
127	                        // Coalesce: append to the existing user turn.
128	                        let last = messages.last_mut().unwrap();
129	                        last.content.extend(blocks);
130	                    } else {
131	                        let msg = Message::builder()
132	                            .role(ConversationRole::User)
133	                            .set_content(Some(blocks))
134	                            .build()
135	                            .expect("role + non-empty content always valid");
136	                        messages.push(msg);
137	                    }
138	                }
139	            }
140	
141	            Item::AssistantMessage { content, .. } => {
142	                flush_user_results(&mut messages, &mut pending_tool_results);
143	                flush_assistant(&mut messages, &mut pending_assistant);
144	                let mut blocks: Vec<ContentBlock> = Vec::new();
145	                for part in content {
146	                    match part {
147	                        ContentPart::Text { text } => {
148	                            blocks.push(ContentBlock::Text(text.clone()));
149	                        }
150	                        ContentPart::ToolUse {
151	                            call_id,
152	                            name,
153	                            args,
154	                        } => {
155	                            let tool_use = ToolUseBlock::builder()
156	                                .tool_use_id(call_id)
157	                                .name(name)
158	                                .input(value_to_document(args))
159	                                .build()
160	                                .expect("tool_use_id + name + input always valid");
161	                            blocks.push(ContentBlock::ToolUse(tool_use));
162	                        }
163	                        ContentPart::Reasoning { .. } => {
164	                            tracing::warn!(
165	                                target: "paigasus::bedrock::translate",
166	                                "dropping ContentPart::Reasoning — round-trip not supported on Bedrock",
167	                            );
168	                        }
169	                        _ => {
170	                            tracing::warn!(
171	                                target: "paigasus::bedrock::translate",
172	                                "unsupported ContentPart variant in AssistantMessage; skipping",
173	                            );
174	                        }
175	                    }
176	                }
177	                if !blocks.is_empty() {
178	                    if messages
179	                        .last()
180	                        .map(|m| m.role == ConversationRole::Assistant)
181	                        .unwrap_or(false)
182	                    {
183	                        // Coalesce: append to the existing assistant turn.
184	                        let last = messages.last_mut().unwrap();
185	                        last.content.extend(blocks);
186	                    } else {
187	                        let msg = Message::builder()
188	                            .role(ConversationRole::Assistant)
189	                            .set_content(Some(blocks))
190	                            .build()
191	                            .expect("role + non-empty content always valid");
192	                        messages.push(msg);
193	                    }
194	                }
195	            }
196	
197	            Item::ToolCall {
198	                call_id,
199	                name,
200	                args,
201	            } => {
202	                // Queue onto the pending assistant turn (flushed when a user
203	                // turn / system / end-of-input is encountered).
204	                let tool_use = ToolUseBlock::builder()
205	                    .tool_use_id(call_id)
206	                    .name(name)
207	                    .input(value_to_document(args))
208	                    .build()
209	                    .expect("tool_use_id + name + input always valid");
210	                pending_assistant.push(ContentBlock::ToolUse(tool_use));
211	            }
212	
213	            Item::ToolResult { call_id, content } => {
214	                // Flush the preceding assistant turn that requested this result.
215	                flush_assistant(&mut messages, &mut pending_assistant);
216	                // Queue onto pending user / tool-result turn.
217	                let result_block = build_tool_result_block(call_id, content);
218	                pending_tool_results.push(ContentBlock::ToolResult(result_block));
219	            }
220	
221	            _ => {
222	                tracing::warn!(
223	                    target: "paigasus::bedrock::translate",
224	                    "unknown Item variant; skipping",
225	                );
226	            }
227	        }
228	    }
229	
230	    // Flush any remaining pending content.
231	    flush_assistant(&mut messages, &mut pending_assistant);
232	    flush_user_results(&mut messages, &mut pending_tool_results);
233	
234	    // Guard: empty conversation.
235	    if messages.is_empty() {
236	        return Err(ModelError::Other(anyhow::anyhow!(
237	            "Bedrock Converse requires at least one non-system message"
238	        )));
239	    }
240	
241	    // Guard: first message must be user — synthesize a minimal user turn.
242	    if messages[0].role == ConversationRole::Assistant {
243	        let placeholder = Message::builder()
244	            .role(ConversationRole::User)
245	            .content(ContentBlock::Text(String::new()))
246	            .build()
247	            .expect("placeholder user turn always valid");
248	        messages.insert(0, placeholder);
249	    }
250	
251	    Ok(TranslatedMessages { system, messages })
252	}
