256	/// Extract and concatenate all text from a `Vec<ContentPart>`.
257	fn text_of(parts: &[ContentPart]) -> String {
258	    let mut s = String::new();
259	    for p in parts {
260	        if let ContentPart::Text { text } = p {
261	            if !s.is_empty() {
262	                s.push('\n');
263	            }
264	            s.push_str(text);
265	        }
266	    }
267	    s
268	}
269	
270	/// Build a `ToolResultBlock` from a call_id + content.
271	fn build_tool_result_block(call_id: &str, content: &[ContentPart]) -> ToolResultBlock {
272	    let text = text_of(content);
273	    ToolResultBlock::builder()
274	        .tool_use_id(call_id)
275	        .content(ToolResultContentBlock::Text(text))
276	        .build()
277	        .expect("tool_use_id + content always valid")
278	}
