282	/// Project [`TranslatedMessages`] into a stable [`serde_json::Value`] for
283	/// snapshot tests. The projection is independent of SDK `Debug` output.
284	#[cfg(test)]
285	pub(crate) fn messages_to_wire_json(tm: &TranslatedMessages) -> Value {
286	    let system: Vec<Value> = tm
287	        .system
288	        .iter()
289	        .map(|s| match s {
290	            SystemContentBlock::Text(t) => json!({"type": "text", "text": t}),
291	            _ => json!({"type": "unknown"}),
292	        })
293	        .collect();
294	
295	    let messages: Vec<Value> = tm
296	        .messages
297	        .iter()
298	        .map(|m| {
299	            let role = match m.role {
300	                ConversationRole::User => "user",
301	                ConversationRole::Assistant => "assistant",
302	                _ => "unknown",
303	            };
304	            let content: Vec<Value> = m
305	                .content
306	                .iter()
307	                .map(|b| match b {
308	                    ContentBlock::Text(t) => json!({"type": "text", "text": t}),
309	                    ContentBlock::ToolUse(tu) => json!({
310	                        "type": "tool_use",
311	                        "toolUseId": tu.tool_use_id,
312	                        "name": tu.name,
313	                    }),
314	                    ContentBlock::ToolResult(tr) => {
315	                        let result_text = tr
316	                            .content
317	                            .iter()
318	                            .find_map(|c| {
319	                                if let ToolResultContentBlock::Text(t) = c {
320	                                    Some(t.as_str())
321	                                } else {
322	                                    None
323	                                }
324	                            })
325	                            .unwrap_or("");
326	                        json!({
327	                            "type": "tool_result",
328	                            "toolUseId": tr.tool_use_id,
329	                            "content": result_text,
330	                        })
331	                    }
332	                    _ => json!({"type": "unknown"}),
333	                })
334	                .collect();
335	            json!({"role": role, "content": content})
336	        })
337	        .collect();
338	
339	    json!({"system": system, "messages": messages})
340	}
